   705	    /// Find `name` through `module`'s glob imports, following glob chains
   706	    /// (`pub use inner::*` re-exports) breadth-first. Each module is visited
   707	    /// at most once, so cyclic globs (`a: use b::*`, `b: use a::*`) are
   708	    /// harmless and the cost is linear in the glob graph.
   709	    fn glob(&self, module: &SymbolId, name: &str, ns: Ns) -> Option<SymbolId> {
   710	        let mut queue: std::collections::VecDeque<&SymbolId> = self.globs.get(module)?.iter().collect();
   711	        let mut seen: BTreeSet<&SymbolId> = BTreeSet::from([module]);
   712	        while let Some(m) = queue.pop_front() {
   713	            if !seen.insert(m) {
   714	                continue;
   715	            }
   716	            if let Some(id) = self.item(m, name, ns) {
   717	                return Some(id.clone());
   718	            }
   719	            if let Some(next) = self.globs.get(m) {
   720	                queue.extend(next.iter());
   721	            }
   722	        }
   723	        None
   724	    }
