   726	    /// Resolve a list of raw type refs to kept relation targets.
   727	    fn refs(&self, module: &SymbolId, raw: &[Segs], self_ty: Option<&SymbolId>, params: InScope<'_>) -> Vec<SymbolId> {
   728	        let mut out = Vec::new();
   729	        for segs in raw {
   730	            // Generic parameters and their associated types (`T`,
   731	            // `T::Output`, `Self::Error`) are not symbols.
   732	            if params.heads(segs) || (segs.len() > 1 && segs[0] == "Self") {
   733	                continue;
   734	            }
   735	            if segs.len() == 1 && PRELUDE.contains(&segs[0].as_str()) && !self.local(module, &segs[0]) {
   736	                continue;
   737	            }
   738	            let (id, _) = self.resolve(module, segs, self_ty, Ns::Type);
   739	            if (keep_ref(&id) || self.internal.contains(&id)) && Some(&id) != self_ty && !out.contains(&id) {
   740	                out.push(id);
   741	            }
   742	        }
   743	        out
   744	    }
