   746	    /// `true` if `name` is defined or imported in `module`.
   747	    fn local(&self, module: &SymbolId, name: &str) -> bool {
   748	        self.items.get(module).is_some_and(|m| m.contains_key(name))
   749	            || self.uses.get(module).is_some_and(|us| us.iter().any(|u| u.alias == name))
   750	    }
   751	
   752	    fn member(&self, module: &SymbolId, m: &RawMember, owner: Option<&SymbolId>, params: InScope<'_>) -> Member {
   753	        Member {
   754	            name: m.name.clone(),
   755	            kind: m.kind,
   756	            ty: m.ty.clone(),
   757	            visibility: m.vis.clone(),
   758	            span: m.span,
   759	            refs: self.refs(module, &m.refs, owner, params),
   760	        }
   761	    }
   762	
   763	    fn add_uses(
   764	        &self,
   765	        cb: &mut Codebase,
   766	        from: &SymbolId,
   767	        module: &SymbolId,
   768	        raw: &[Segs],
   769	        self_ty: Option<&SymbolId>,
   770	        params: InScope<'_>,
   771	    ) {
   772	        for t in self.refs(module, raw, self_ty, params) {
   773	            let c = if self.internal.contains(&t) { Confidence::Exact } else { Confidence::External };
   774	            cb.add_relation(Relation::new(from.clone(), t, RelationKind::Uses, c));
   775	        }
   776	    }
