   195	fn run(cli: Cli) -> Result<ExitCode, String> {
   196	    match cli.cmd {
   197	        Cmd::Generate(g) => generate(&g),
   198	        Cmd::Model(m) => {
   199	            let (codebase, _) = extract(&m.path, &m.source, external(&m.external)?)?;
   200	            println!("{}", serde_json::to_string_pretty(&codebase).map_err(|e| e.to_string())?);
   201	            Ok(ExitCode::SUCCESS)
   202	        }
   203	        Cmd::Resolve(r) => resolve(&r),
   204	        Cmd::SealCheck(s) => {
   205	            let only: BTreeSet<String> = s.topics.iter().cloned().collect();
   206	            let ctx = Ctx::load(&s.corpus)?;
   207	            let lock = match &ctx.lock_text {
   208	                Some(text) => Lock::parse(text).map_err(|e| format!("{}: {e}", ctx.lock_path.display()))?,
   209	                None => return Err(format!("{} does not exist", ctx.lock_path.display())),
   210	            };
   211	            let report = seal::seal_check(
   212	                &lock,
   213	                seal::LOCK_FILE,
   214	                &ctx.topics,
   215	                &ctx.codebase,
   216	                (!only.is_empty()).then_some(&only),
   217	            );
   218	            print_report(&report, &s.corpus)
   219	        }
   220	        Cmd::Verify(c) => {
   221	            let ctx = Ctx::load(&c)?;
   222	            let report = seal::verify(ctx.lock_text.as_deref(), seal::LOCK_FILE, &ctx.topics, &ctx.codebase);
   223	            print_report(&report, &c)
   224	        }
   225	        Cmd::Stale(s) => stale(&s),
   226	        Cmd::Seal(SealCmd::Sign(s)) => sign(&s),
   227	    }
   228	}
