   232	fn generate(g: &Generate) -> Result<ExitCode, String> {
   233	    let mut opts = Options::default();
   234	    opts.corpus.min_calls = g.min_calls;
   235	    opts.corpus.include_private = !g.public_only;
   236	    opts.corpus.emit_model = !g.no_model;
   237	    opts.corpus.pretty_json = g.pretty;
   238	    if g.owner_lanes {
   239	        opts.corpus.external_lanes = ExternalLanes::Owner;
   240	    }
   241	    let (codebase, _) = extract(&g.path, &g.source, external(&g.external)?)?;
   242	    let corpus = sealmap::generate(&codebase, &opts.corpus);
   243	    if g.check {
   244	        let report = corpus::verify(&g.out, &corpus).map_err(|e| e.to_string())?;
   245	        for e in &report.entries {
   246	            println!("{:<9} {}", e.drift.to_string(), e.path);
   247	        }
   248	        if report.is_clean() {
   249	            eprintln!("sealmap: {} matches a fresh generation ({} files)", g.out.display(), report.checked);
   250	            return Ok(ExitCode::SUCCESS);
   251	        }
   252	        eprintln!("sealmap: {} files differ from a fresh generation", report.entries.len());
   253	        return Ok(ExitCode::from(1));
   254	    }
   255	    let report = corpus::write(&g.out, &corpus).map_err(|e| e.to_string())?;
   256	    let stats = codebase.stats();
   257	    let removed = report.count(Drift::Orphaned);
   258	    eprintln!(
   259	        "sealmap: {} files, {} symbols, {} sequences → {} ({} written, {} removed, {} unchanged)",
   260	        stats.files,
   261	        stats.symbols,
   262	        corpus.index.fragments().filter(|f| f.kind == corpus::FragmentKind::Sequence).count(),
   263	        g.out.display(),
   264	        report.entries.len() - removed,
   265	        removed,
   266	        report.checked - (report.entries.len() - removed),
   267	    );
   268	    Ok(ExitCode::SUCCESS)
   269	}
