   340	/// * a topic with a `sealed:` pointer but no entry → [`Class::LockFault`];
   341	/// * a `sym:` citation in a topic without an entry →
   342	///   [`Class::UnsealedCitation`].
   343	///
   344	/// Topics with neither a seal nor a citation are listed in
   345	/// [`SealReport::unsealed_topics`] and do not fail the gate, so a corpus can
   346	/// migrate one topic at a time.
   347	///
   348	/// ```
   349	/// use std::collections::BTreeMap;
   350	/// use sealmap_corpus::seal::{Class, verify};
   351	/// use sealmap_model::{Codebase, SourcePath};
   352	///
   353	/// let mut topics = BTreeMap::new();
   354	/// topics.insert(SourcePath::new("a/01-x.md").unwrap(), "---\nid: A-01\n---\nCites `sym:cargo shop . Db#`.\n".to_owned());
   355	/// let report = verify(None, "seals.lock", &topics, &Codebase::new("shop"));
   356	/// assert!(!report.passes());
   357	/// assert_eq!(report.count(Class::UnsealedCitation), 1);
   358	/// ```
   359	pub fn verify(lock_text: Option<&str>, lock_name: &str, topics: &Topics, codebase: &Codebase) -> SealReport {
   360	    let lock = match lock_text.map(Lock::parse) {
   361	        None => Lock::new(),
   362	        Some(Ok(lock)) => lock,
   363	        Some(Err(e)) => {
   364	            return SealReport {
   365	                findings: vec![fault(None, None, format!("{lock_name}: {e}"))],
   366	                unsealed_topics: Vec::new(),
   367	            };
   368	        }
   369	    };
   370	    let mut report = seal_check(&lock, lock_name, topics, codebase, None);
   371	    if let Some(text) = lock_text {
   372	        if lock.to_toml() != text {
   373	            report.findings.push(fault(None, None, format!("{lock_name}: {}", LockError::NonCanonical)));
   374	        }
   375	    }
   376	    for (path, text) in topics {
   377	        let Some(id) = topic_id(text) else { continue };
   378	        if lock.by_file(path).is_some() {
   379	            continue;
   380	        }
   381	        let cited = citations(text);
   382	        let has_pointer = !pointers(text).is_empty();
   383	        if has_pointer {
   384	            report.findings.push(fault(
   385	                Some(id.clone()),
   386	                Some(path.clone()),
   387	                format!("the topic has a `sealed:` pointer but {lock_name} has no entry for {path}"),
   388	            ));
   389	        }
   390	        unsealed_citations(&id, path, &cited, |_| false, &mut report.findings);
   391	        if cited.is_empty() && !has_pointer {
   392	            report.unsealed_topics.push(path.clone());
   393	        }
   394	    }
   395	    report.findings.sort();
   396	    report
   397	}
