     1	//! Per-file collection on big stacks with a panic guard.
     2	//!
     3	//! Recursive-descent parsers and body walkers use stack in proportion to
     4	//! syntactic nesting, and generated files can nest far deeper than a 2 MiB
     5	//! thread stack allows (measured on syn: one level of `UInt<UInt<..>>` costs
     6	//! about 40 KiB in a debug build). [`map_isolated`] therefore runs every job
     7	//! on threads with [`COLLECT_STACK_BYTES`] of stack, and turns a panic in one
     8	//! job into a value instead of aborting the run. A stack overflow is an abort
     9	//! and cannot be caught, which is why the big stack (and a language adapter's own
    10	//! depth cap) are what actually matter.
    11	//!
    12	//! ```
    13	//! use sealmap_extract::isolate::{COLLECT_STACK_BYTES, map_isolated};
    14	//!
    15	//! let files = ["ok", "boom", "fine"];
    16	//! let out = map_isolated(
    17	//!     &files,
    18	//!     COLLECT_STACK_BYTES,
    19	//!     |f| if *f == "boom" { panic!("bad input") } else { f.len() },
    20	//!     |_, why| { assert_eq!(why, "bad input"); 0 },
    21	//! );
    22	//! assert_eq!(out, [2, 0, 4]);
    23	//! ```
    24	
    25	use std::any::Any;
    26	
    27	/// Default stack for collector threads. Pages are only committed when
    28	/// touched, so the cost is address space (64 MiB × threads), not memory.
    29	pub const COLLECT_STACK_BYTES: usize = 64 * 1024 * 1024;
    30	
    31	/// Map `job` over `items`, in input order, on threads with `stack_bytes` of
    32	/// stack. A panicking job yields `on_panic(item, message)` instead.
    33	///
    34	/// With the `parallel` feature the jobs run on a dedicated rayon pool;
    35	/// otherwise (or if the pool cannot be built) on one scoped thread with the
    36	/// same stack, so behaviour does not depend on the feature. If even that
    37	/// thread cannot be spawned, the jobs run on the calling thread.
    38	pub fn map_isolated<T, R, F, P>(items: &[T], stack_bytes: usize, job: F, on_panic: P) -> Vec<R>
    39	where
    40	    T: Sync,
    41	    R: Send,
    42	    F: Fn(&T) -> R + Sync,
    43	    P: Fn(&T, String) -> R + Sync,
    44	{
    45	    let one = |item: &T| {
    46	        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| job(item)))
    47	            .unwrap_or_else(|e| on_panic(item, panic_message(e.as_ref())))
    48	    };
    49	    #[cfg(feature = "parallel")]
    50	    {
    51	        use rayon::prelude::*;
    52	        if let Ok(pool) = rayon::ThreadPoolBuilder::new().stack_size(stack_bytes).build() {
    53	            return pool.install(|| items.par_iter().map(one).collect());
    54	        }
    55	    }
    56	    std::thread::scope(|scope| {
    57	        std::thread::Builder::new()
    58	            .name("sealmap-collect".into())
    59	            .stack_size(stack_bytes)
    60	            .spawn_scoped(scope, || items.iter().map(one).collect())
    61	            .ok()
    62	            .and_then(|h| h.join().ok())
    63	    })
    64	    .unwrap_or_else(|| items.iter().map(one).collect())
    65	}
