    67	/// The message of a caught panic payload (`&str` or `String`), or
    68	/// `unknown panic`.
    69	pub fn panic_message(payload: &(dyn Any + Send)) -> String {
    70	    payload
    71	        .downcast_ref::<&str>()
    72	        .map(|s| (*s).to_owned())
    73	        .or_else(|| payload.downcast_ref::<String>().cloned())
    74	        .unwrap_or_else(|| "unknown panic".into())
    75	}
