   148	/// Extract a [`Codebase`](sealmap_model::Codebase) from the `.rs` (and `Cargo.toml`) files in
   149	/// `sources`. Never fails: unparsable files are reported in
   150	/// [`Extraction::diagnostics`].
   151	pub fn extract(sources: &SourceSet, options: &RustOptions) -> Extraction {
   152	    let plan = layout::plan(sources, &options.name);
   153	    let jobs: Vec<_> = plan
   154	        .into_iter()
   155	        .filter(|(_, role)| options.include_tests || role.target <= layout::TargetKind::Bin)
   156	        .filter_map(|(path, role)| sources.get(&path).map(|text| (path.clone(), role, text)))
   157	        .collect();
   158	
   159	    let files = collect_all(&jobs, options);
   160	
   161	    let (codebase, diagnostics) = resolve::build(&options.name, files, options);
   162	    Extraction { codebase, diagnostics }
   163	}
