   165	type Job<'a> = (SourcePath, layout::FileRole, &'a str);
   166	
   167	/// Pass 1 over every file, isolated per file (big stacks, panic guard; see
   168	/// [`sealmap_extract::isolate`]). A panic while collecting one file degrades
   169	/// that file to a diagnostic instead of aborting the run.
   170	fn collect_all(jobs: &[Job<'_>], options: &RustOptions) -> Vec<raw::RawFile> {
   171	    map_isolated(
   172	        jobs,
   173	        COLLECT_STACK_BYTES,
   174	        |(p, r, t)| collect::collect_file(p, r, t, options),
   175	        |(p, r, t), why| collect::failed_file(p, r, t, format!("1:1: internal error while collecting: {why}")),
   176	    )
   177	}
