   838	    /// Resolve a method call. Returns `None` only when the call should be
   839	    /// dropped outright.
   840	    fn method(&self, ctx: &FlowCtx<'_>, recv: &Recv, name: &str) -> Option<(SymbolId, Confidence)> {
   841	        let ty = match recv {
   842	            Recv::SelfValue => ctx.self_ty.cloned(),
   843	            Recv::SelfField(field) => match ctx.self_ty.and_then(|ty| self.fields.get(ty)?.field(field)) {
   844	                Some((module, params, refs)) => self.receiver_type(module, refs, None, params),
   845	                None => return Some(self.by_name_only(name)),
   846	            },
   847	            Recv::Typed(refs) => self.receiver_type(ctx.module, refs, ctx.self_ty, ctx.params),
   848	            Recv::Untyped => return Some(self.by_name_only(name)),
   849	            Recv::Derived(origin) => {
   850	                return Some(if self.internal_origin(ctx, origin) {
   851	                    self.by_name_only(name)
   852	                } else {
   853	                    (ids::unresolved_method_id(name), Confidence::External)
   854	                });
   855	            }
   856	            Recv::Returned(_) | Recv::Computed(_) | Recv::Unknown => None,
   857	        };
   858	        let Some(ty) = ty else { return Some((ids::unresolved_method_id(name), Confidence::External)) };
   859	        if let Some(id) = self.methods.get(&ty).and_then(|m| m.get(name)) {
   860	            return Some((id.clone(), Confidence::Exact));
   861	        }
   862	        if self.trait_methods.get(&ty).is_some_and(|n| n.contains(name)) {
   863	            return Some((ids::method_id(&ty, None, name), Confidence::Exact));
   864	        }
   865	        for tr in self.impls.get(&ty).into_iter().flatten() {
   866	            if self.trait_methods.get(tr).is_some_and(|n| n.contains(name)) {
   867	                return Some((ids::method_id(tr, None, name), Confidence::Exact));
   868	            }
   869	        }
   870	        // Known type, method not defined in the codebase: a derived or std
   871	        // trait method on an internal type, or a dependency's method.
   872	        Some((undefined_member(&ty, name), Confidence::External))
   873	    }
   874	
   875	    /// Does a [`Recv::Derived`] value come from code in the analysed
   876	    /// codebase? `self`, a field or typed value whose type mentions an
   877	    /// internal type, an internal function's result, or a plain variable of
   878	    /// unevident type do; a value of `std` or third-party type, a third-party
   879	    /// function's result and anything unknown do not.
   880	    fn internal_origin(&self, ctx: &FlowCtx<'_>, origin: &Recv) -> bool {
   881	        let any_internal = |module: &SymbolId, refs: &[Segs], self_ty: Option<&SymbolId>, params: InScope<'_>| {
   882	            refs.iter().any(|segs| self.internal.contains(&self.resolve_in(module, segs, self_ty, Ns::Type, params).0))
   883	        };
   884	        match origin {
   885	            Recv::SelfValue | Recv::Untyped => true,
   886	            Recv::SelfField(field) => match ctx.self_ty.and_then(|ty| self.fields.get(ty)?.field(field)) {
   887	                Some((module, params, refs)) => any_internal(module, refs, None, params),
   888	                None => true,
   889	            },
   890	            Recv::Typed(refs) => any_internal(ctx.module, refs, ctx.self_ty, ctx.params),
   891	            Recv::Returned(segs) => {
   892	                self.internal.contains(&self.resolve_in(ctx.module, segs, ctx.self_ty, Ns::Value, ctx.params).0)
   893	            }
   894	            Recv::Derived(inner) | Recv::Computed(inner) => self.internal_origin(ctx, inner),
   895	            Recv::Unknown => false,
   896	        }
   897	    }
