   900	    /// (outermost first). Smart pointers are looked through; any other
   901	    /// wrapper (`Vec`, `Option`, `Mutex`, ...) *is* the receiver. A generic
   902	    /// parameter has no concrete type.
   903	    fn receiver_type(
   904	        &self,
   905	        module: &SymbolId,
   906	        refs: &[Segs],
   907	        self_ty: Option<&SymbolId>,
