   175	
   176	```mermaid
   177	stateDiagram-v2
   185	    UT["untyped variable<br/>resolve.rs:848"]
   186	    DV["derived part of another value<br/>resolve.rs:849"]
   187	    DR["returned, computed or unknown:<br/>dropped<br/>resolve.rs:856"]
   188	    RT["receiver_type: look through Box,<br/>Arc, Rc and guards<br/>resolve.rs:903"]
   189	    LK{"method on the type, on the trait,<br/>or on a trait it implements?<br/>resolve.rs:859-869"}
